export function formatGameScore(p1Points: number, p2Points: number): [string, string] {
  if (p1Points >= 3 && p2Points >= 3) {
    if (p1Points === p2Points) return ['40', '40']; // Deuce
    if (p1Points > p2Points) return ['AD', '40'];
    return ['40', 'AD'];
  }
  const scoreMap = ['0', '15', '30', '40'];
  return [scoreMap[Math.min(3, p1Points)], scoreMap[Math.min(3, p2Points)]];
}

export function simulateFullMatch(
  player1: Player,
  player2: Player,
  surface: SurfaceType,
  setsToWin: 2 | 3 = 2
): { score: MatchScore; winnerId: string } {
  const sets: Array<[number, number]> = [];
  const tiebreaks: Array<[number, number] | null> = [];

  let p1SetsWon = 0;
  let p2SetsWon = 0;

  const stats: MatchDetailedStats = {
    aces: [0, 0],
    doubleFaults: [0, 0],
    firstServePercentage: [0, 0],
    firstServePointsWon: [0, 0],
    secondServePointsWon: [0, 0],
    firstServesAttempted: [0, 0],
    firstServesIn: [0, 0],
    breakPointsConverted: [0, 0],
    breakPointsTotal: [0, 0],
    winners: [0, 0],
    unforcedErrors: [0, 0],
    totalPointsWon: [0, 0],
    fastestServeKmH: [
      Math.round(200 + (player1.stats.serve - 70) * 0.8 + Math.random() * 10),
      Math.round(200 + (player2.stats.serve - 70) * 0.8 + Math.random() * 10),
    ],
  };

  let server: 1 | 2 = Math.random() > 0.5 ? 1 : 2;

  while (p1SetsWon < setsToWin && p2SetsWon < setsToWin) {
    let p1Games = 0;
    let p2Games = 0;

    while (true) {
      // Check set finish
      if (p1Games >= 6 && p1Games - p2Games >= 2) {
        sets.push([p1Games, p2Games]);
        tiebreaks.push(null);
        p1SetsWon++;
        break;
      }
      if (p2Games >= 6 && p2Games - p1Games >= 2) {
        sets.push([p1Games, p2Games]);
        tiebreaks.push(null);
        p2SetsWon++;
        break;
      }

      // Tiebreak at 6-6
      if (p1Games === 6 && p2Games === 6) {
        let p1Tb = 0;
        let p2Tb = 0;

        while ((p1Tb < 7 && p2Tb < 7) || Math.abs(p1Tb - p2Tb) < 2) {
          const pt = simulateSinglePoint(player1, player2, surface, server, true, p1Tb, p2Tb);
          if (pt.winner === 1) {
            p1Tb++;
            stats.totalPointsWon[0]++;
          } else {
            p2Tb++;
            stats.totalPointsWon[1]++;
          }
          recordServeStats(stats, pt);
          if (pt.outcomeType === 'ace') stats.aces[pt.winner - 1]++;
          if (pt.outcomeType === 'double_fault') stats.doubleFaults[pt.winner === 1 ? 1 : 0]++;
          if (pt.outcomeType === 'winner') stats.winners[pt.winner - 1]++;
          if (pt.outcomeType === 'unforced_error') stats.unforcedErrors[pt.winner === 1 ? 1 : 0]++;

          if ((p1Tb + p2Tb) % 2 === 1) {
            server = server === 1 ? 2 : 1;
          }
        }

        if (p1Tb > p2Tb) {
          p1Games++;
          p1SetsWon++;
        } else {
          p2Games++;
          p2SetsWon++;
        }

        sets.push([p1Games, p2Games]);
        tiebreaks.push([p1Tb, p2Tb]);
        break;
      }

      // Regular Game simulation
      let p1Points = 0;
      let p2Points = 0;
      const initialServer = server;

      while (true) {
        const pt = simulateSinglePoint(player1, player2, surface, server, false, p1Points, p2Points);
        if (pt.winner === 1) {
          p1Points++;
          stats.totalPointsWon[0]++;
        } else {
          p2Points++;
          stats.totalPointsWon[1]++;
        }
        recordServeStats(stats, pt);

        if (pt.outcomeType === 'ace') stats.aces[pt.winner - 1]++;
        if (pt.outcomeType === 'double_fault') stats.doubleFaults[pt.winner === 1 ? 1 : 0]++;
        if (pt.outcomeType === 'winner') stats.winners[pt.winner - 1]++;
        if (pt.outcomeType === 'unforced_error') stats.unforcedErrors[pt.winner === 1 ? 1 : 0]++;

        // Break point check
        if (server === 1 && p2Points >= 3 && p2Points > p1Points) {
          stats.breakPointsTotal[1]++;
        } else if (server === 2 && p1Points >= 3 && p1Points > p2Points) {
          stats.breakPointsTotal[0]++;
        }

        // Win Game check
        if (p1Points >= 4 && p1Points - p2Points >= 2) {
          p1Games++;
          if (initialServer === 2) stats.breakPointsConverted[0]++;
          break;
        }
        if (p2Points >= 4 && p2Points - p1Points >= 2) {
          p2Games++;
          if (initialServer === 1) stats.breakPointsConverted[1]++;
          break;
        }
      }

      server = server === 1 ? 2 : 1;
    }
  }

  const winnerId = p1SetsWon > p2SetsWon ? player1.id : player2.id;
  const durationMinutes = Math.round(45 * sets.length + Math.random() * 30);

  return {
    winnerId,
    score: {
      sets,
      tiebreaks,
      winnerId,
      durationMinutes,
      stats,
    },
  };
}

import React, { useEffect, useRef, useState } from 'react';
import { Play, Pause, FastForward, RotateCcw, Volume2, VolumeX, CheckCircle, ArrowLeft } from 'lucide-react';
import { Match, MatchDetailedStats, MatchScore, Player, SurfaceType } from '../types';
import { formatGameScore, recordServeStats, simulateSinglePoint } from '../engine/tennisEngine';
import { soundFx } from '../utils/audio';

interface MatchViewerProps {
  match: Match;
  player1: Player;
  player2: Player;
  surface: SurfaceType;
  setsToWin: 2 | 3;
  onMatchFinished: (matchId: string, winnerId: string, score: MatchScore) => void;
  onBackToBracket: () => void;
}

export const MatchViewer: React.FC<MatchViewerProps> = ({
  match,
  player1,
  player2,
  surface,
  setsToWin,
  onMatchFinished,
  onBackToBracket,
}) => {
  // Live state
  const [sets, setSets] = useState<Array<[number, number]>>(
    match.score ? match.score.sets : [[0, 0]]
  );
  const [currentSetIdx, setCurrentSetIdx] = useState<number>(
    match.score ? match.score.sets.length - 1 : 0
  );
  const [currentGamePoints, setCurrentGamePoints] = useState<[number, number]>([0, 0]);
  const [server, setServer] = useState<1 | 2>(1);
  const [inTiebreak, setInTiebreak] = useState<boolean>(false);
  const [tiebreakScore, setTiebreakScore] = useState<[number, number]>([0, 0]);
  const [isMatchOver, setIsMatchOver] = useState<boolean>(match.isCompleted);
  const [matchWinner, setMatchWinner] = useState<string | null>(match.winnerId || null);
  const [pointLogs, setPointLogs] = useState<string[]>([]);
  const [isAutoPlaying, setIsAutoPlaying] = useState<boolean>(false);
  const [autoPlaySpeed, setAutoPlaySpeed] = useState<number>(800); // ms per point
  const [isMuted, setIsMuted] = useState<boolean>(soundFx.getMuted());
  const [ballPos, setBallPos] = useState<{ x: number; y: number }>({ x: 50, y: 50 });
  const [isBallActive, setIsBallActive] = useState<boolean>(false);

  // Match stats
  const [stats, setStats] = useState<MatchDetailedStats>(
    match.score?.stats || {
      aces: [0, 0],
      doubleFaults: [0, 0],
      firstServePercentage: [0, 0],
      firstServePointsWon: [0, 0],
      secondServePointsWon: [0, 0],
      firstServesAttempted: [0, 0],
      firstServesIn: [0, 0],
      breakPointsConverted: [0, 0],
      breakPointsTotal: [0, 0],
      winners: [0, 0],
      unforcedErrors: [0, 0],
      totalPointsWon: [0, 0],
      fastestServeKmH: [
        Math.round(205 + (player1.stats.serve - 70) * 0.7),
        Math.round(205 + (player2.stats.serve - 70) * 0.7),
      ],
    }
  );

  const logsContainerRef = useRef<HTMLDivElement>(null);

  // Auto-scroll internal log container only (without shifting browser window)
  useEffect(() => {
    if (logsContainerRef.current) {
      logsContainerRef.current.scrollTop = logsContainerRef.current.scrollHeight;
    }
  }, [pointLogs]);

  // Point simulator step
  const handlePlayNextPoint = () => {
    if (isMatchOver) return;

    const currentP1Games = sets[currentSetIdx] ? sets[currentSetIdx][0] : 0;
    const currentP2Games = sets[currentSetIdx] ? sets[currentSetIdx][1] : 0;

    let p1Pt = inTiebreak ? tiebreakScore[0] : currentGamePoints[0];
    let p2Pt = inTiebreak ? tiebreakScore[1] : currentGamePoints[1];

    const ptResult = simulateSinglePoint(
      player1,
      player2,
      surface,
      server,
      inTiebreak,
      p1Pt,
      p2Pt
    );

    // Audio SFX
    if (ptResult.outcomeType === 'ace') {
      soundFx.playAce();
    } else if (ptResult.outcomeType === 'double_fault') {
      // no hit
    } else {
      soundFx.playRacketHit(ptResult.outcomeType === 'winner');
    }

    // Visual Ball Animation
    setIsBallActive(true);
    setBallPos(ptResult.ballPath[ptResult.ballPath.length - 1]);

    // Update Stats
    const updatedStats = { ...stats };
    if (ptResult.winner === 1) updatedStats.totalPointsWon[0]++;
    else updatedStats.totalPointsWon[1]++;

    if (ptResult.outcomeType === 'ace') updatedStats.aces[ptResult.winner - 1]++;
    if (ptResult.outcomeType === 'double_fault') updatedStats.doubleFaults[ptResult.winner === 1 ? 1 : 0]++;
    if (ptResult.outcomeType === 'winner') updatedStats.winners[ptResult.winner - 1]++;
    if (ptResult.outcomeType === 'unforced_error') updatedStats.unforcedErrors[ptResult.winner === 1 ? 1 : 0]++;
    recordServeStats(updatedStats, ptResult);
    setStats(updatedStats);

    // Add log
    setPointLogs((prev) => [...prev.slice(-40), ptResult.descriptionRu]);

    // Handle Tiebreak logic
    if (inTiebreak) {
      const newTb: [number, number] = [
        ptResult.winner === 1 ? p1Pt + 1 : p1Pt,
        ptResult.winner === 2 ? p2Pt + 1 : p2Pt,
      ];
      setTiebreakScore(newTb);

      // Server toggle in tiebreak (every 2 points after 1st point)
      if ((newTb[0] + newTb[1]) % 2 === 1) {
        setServer((s) => (s === 1 ? 2 : 1));
      }

      // Check Tiebreak won (7 points with 2 pt margin)
      if ((newTb[0] >= 7 || newTb[1] >= 7) && Math.abs(newTb[0] - newTb[1]) >= 2) {
        const tbWinner = newTb[0] > newTb[1] ? 1 : 2;
        handleSetWon(tbWinner, true, sets);
      }
      return;
    }

    // Handle Regular Game Logic
    let newP1Pt = ptResult.winner === 1 ? p1Pt + 1 : p1Pt;
    let newP2Pt = ptResult.winner === 2 ? p2Pt + 1 : p2Pt;

    // Game won check
    if (newP1Pt >= 4 && newP1Pt - newP2Pt >= 2) {
      handleGameWon(1);
    } else if (newP2Pt >= 4 && newP2Pt - newP1Pt >= 2) {
      handleGameWon(2);
    } else {
      setCurrentGamePoints([newP1Pt, newP2Pt]);
    }
  };

  const handleGameWon = (gameWinner: 1 | 2) => {
    soundFx.playCrowdApplause();
    setCurrentGamePoints([0, 0]);
    const updatedSets = [...sets];
    const currSet = [...updatedSets[currentSetIdx]] as [number, number];

    if (gameWinner === 1) currSet[0]++;
    else currSet[1]++;
    updatedSets[currentSetIdx] = currSet;
    setSets(updatedSets);

    // Switch server
    setServer((s) => (s === 1 ? 2 : 1));

    // Check Set Won
    if (currSet[0] >= 6 && currSet[0] - currSet[1] >= 2) {
      handleSetWon(1, false, updatedSets);
    } else if (currSet[1] >= 6 && currSet[1] - currSet[0] >= 2) {
      handleSetWon(2, false, updatedSets);
    } else if (currSet[0] === 6 && currSet[1] === 6) {
      // Enter Tiebreak!
      setInTiebreak(true);
      setTiebreakScore([0, 0]);
      setPointLogs((prev) => [...prev, '🔥 ТАЙ-БРЕЙК ДО 7 ОЧКОВ!']);
    }
  };

  const handleSetWon = (setWinner: 1 | 2, wasTiebreak: boolean, currentSets: Array<[number, number]>) => {
    setInTiebreak(false);
    setTiebreakScore([0, 0]);
    setCurrentGamePoints([0, 0]);

    let updatedSets = JSON.parse(JSON.stringify(currentSets)) as Array<[number, number]>;
    if (wasTiebreak) {
      const curr = [...updatedSets[currentSetIdx]] as [number, number];
      if (setWinner === 1) curr[0] = 7;
      else curr[1] = 7;
      updatedSets[currentSetIdx] = curr;
    }

    setSets(updatedSets);

    // Count sets won
    let p1Sets = 0;
    let p2Sets = 0;
    updatedSets.forEach((s) => {
      if (s[0] > s[1]) p1Sets++;
      else if (s[1] > s[0]) p2Sets++;
    });

    const setWinnerPlayer = setWinner === 1 ? player1 : player2;
    setPointLogs((prev) => [...prev, `🏆 СЕТ ЗА ${setWinnerPlayer.nameRu.toUpperCase()}!`]);

    // Check Match Won
    if (p1Sets === setsToWin || p2Sets === setsToWin) {
      const winnerId = p1Sets === setsToWin ? player1.id : player2.id;
      setIsMatchOver(true);
      setMatchWinner(winnerId);
      setIsAutoPlaying(false);
      soundFx.playWinnerFanfare();

      const finalScore: MatchScore = {
        sets: updatedSets,
        winnerId,
        durationMinutes: 45 * updatedSets.length + Math.floor(Math.random() * 20),
        stats,
      };

      onMatchFinished(match.id, winnerId, finalScore);
    } else {
      // Start next set
      const nextSets = [...updatedSets, [0, 0]] as Array<[number, number]>;
      setSets(nextSets);
      setCurrentSetIdx((idx) => idx + 1);
    }
  };

  // Auto-play timer
  useEffect(() => {
    let timer: NodeJS.Timeout | null = null;
    if (isAutoPlaying && !isMatchOver) {
      timer = setInterval(() => {
        handlePlayNextPoint();
      }, autoPlaySpeed);
    }
    return () => {
      if (timer) clearInterval(timer);
    };
  }, [isAutoPlaying, isMatchOver, autoPlaySpeed, sets, currentSetIdx, currentGamePoints, inTiebreak, tiebreakScore, server]);

  const gameScoreFormatted = formatGameScore(currentGamePoints[0], currentGamePoints[1]);

  return (
    <div className="space-y-6 max-w-5xl mx-auto pb-12">
      {/* Top Bar with Back button & Mute */}
      <div className="flex items-center justify-between">

    setSeason(newSeason);
    setPlayers(updatedPlayers);
    triggerAutoSave(newSeason, updatedPlayers);
  };

  // Next tournament in calendar
  const handleNextTournament = () => {
    const nextIdx = season.currentTournamentIndex + 1;
    if (nextIdx < season.tournaments.length) {
      setSeason({
        ...season,
        currentTournamentIndex: nextIdx,
      });
      setCurrentTab('tournament');
      window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
      // Season completed! Show Year-End transition modal
      const atpNo1 = players.find((p) => p.tour === 'ATP' && p.rank === 1) || null;
      const wtaNo1 = players.find((p) => p.tour === 'WTA' && p.rank === 1) || null;

      setTransitionReport({
        year: season.year,
        nextYear: season.year + 1,
        atpChampion: atpNo1,
        wtaChampion: wtaNo1,
      });
    }
  };

  // Advance to next season year
  const handleStartNextSeasonYear = () => {
    if (!transitionReport) return;
    const nextYear = transitionReport.nextYear;
    setTransitionReport(null);

    // Evolve players: age + 1, slight rating growth or decline
    const evolvedPlayers = players.map((p) => {
      const isYoung = p.age < 23;
      const isVeteran = p.age > 33;
      const delta = isYoung ? 1 : isVeteran ? -1 : 0;

      return {
        ...p,
        age: p.age + 1,
        stats: {
          ...p.stats,
          serve: Math.min(99, Math.max(50, p.stats.serve + delta)),
          forehand: Math.min(99, Math.max(50, p.stats.forehand + delta)),
          backhand: Math.min(99, Math.max(50, p.stats.backhand + delta)),
          speed: Math.min(99, Math.max(50, p.stats.speed + (isVeteran ? -2 : delta))),
        },
      };
    });

    const newSeason = initializeNewSeason(evolvedPlayers, nextYear);
    setSeason(newSeason);
    setPlayers(evolvedPlayers);
    triggerAutoSave(newSeason, evolvedPlayers);
    setCurrentTab('tournament');
  };

