    setSeason(repaired);
    setPlayers(impPlayers);
    triggerAutoSave(repaired, impPlayers);
    showSaveToast('Сохранение успешно импортировано');
  };

  const handleResetSeason = () => {
    const initialP = getInitialPlayers();
