131: export function repairTournamentBracket(tournament: Tournament, allPlayers: Player[]): Tournament {
132:   const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
133:   const eligiblePlayers = allPlayers
134:     .filter((p) => p.tour === updatedTournament.tour && !p.retired)
135:     .sort((a, b) => a.rank - b.rank);
136: 
137:   const numRounds = Math.log2(updatedTournament.drawSize);
138: 
139:   // Group matches by round
140:   const roundMatchesMap = new Map<number, Match[]>();
141:   for (let r = 0; r < numRounds; r++) {
142:     roundMatchesMap.set(r, updatedTournament.matches.filter((m) => m.round === r));
143:   }
144: 
145:   // 1. Ensure all nextMatchId / nextMatchSlot links are completely valid
146:   for (let round = 0; round < numRounds - 1; round++) {
147:     const currMatches = roundMatchesMap.get(round) || [];
148:     const nextMatches = roundMatchesMap.get(round + 1) || [];
149: 
150:     for (let i = 0; i < currMatches.length; i++) {
151:       const targetNextMatch = nextMatches[Math.floor(i / 2)];
152:       if (targetNextMatch) {
153:         currMatches[i].nextMatchId = targetNextMatch.id;
154:         currMatches[i].nextMatchSlot = (i % 2 === 0 ? 1 : 2);
155:       }
156:     }
157:   }
158: 
159:   // 2. Fix missing players in Round 0
160:   const r0Matches = roundMatchesMap.get(0) || [];
161:   const assignedPlayerIds = new Set<string>();
162:   r0Matches.forEach((m) => {
163:     if (m.player1Id) assignedPlayerIds.add(m.player1Id);
164:     if (m.player2Id) assignedPlayerIds.add(m.player2Id);
165:   });
166: 
167:   const unassignedPlayers = eligiblePlayers.filter((p) => !assignedPlayerIds.has(p.id));
168:   let unassignedIdx = 0;
169: 
170:   r0Matches.forEach((m) => {
171:     if (!m.player1Id && unassignedIdx < unassignedPlayers.length) {
172:       m.player1Id = unassignedPlayers[unassignedIdx++].id;
173:       const pObj = allPlayers.find((p) => p.id === m.player1Id);
174:       if (pObj && pObj.rank <= 32) m.seed1 = pObj.rank;
175:     }
176:     if (!m.player2Id && unassignedIdx < unassignedPlayers.length) {
177:       m.player2Id = unassignedPlayers[unassignedIdx++].id;
178:       const pObj = allPlayers.find((p) => p.id === m.player2Id);
179:       if (pObj && pObj.rank <= 32) m.seed2 = pObj.rank;
180:     }
181:   });
182: 
183:   // 3. Propagate completed match winners forward to next round matches
184:   for (let round = 0; round < numRounds - 1; round++) {
185:     const currMatches = roundMatchesMap.get(round) || [];
186:     for (const match of currMatches) {
187:       if (match.isCompleted && match.winnerId && match.nextMatchId) {
188:         const nextMatch = updatedTournament.matches.find((m) => m.id === match.nextMatchId);
189:         if (nextMatch) {
190:           if (match.nextMatchSlot === 1) {
191:             nextMatch.player1Id = match.winnerId;
192:             const pObj = allPlayers.find((p) => p.id === match.winnerId);
193:             if (pObj && pObj.rank <= 32) nextMatch.seed1 = pObj.rank;
194:           } else {
195:             nextMatch.player2Id = match.winnerId;
196:             const pObj = allPlayers.find((p) => p.id === match.winnerId);
197:             if (pObj && pObj.rank <= 32) nextMatch.seed2 = pObj.rank;
198:           }
199:         }
200:       }
201:     }
202:   }
203: 
204:   // 4. Check if final completed
205:   const finalMatch = updatedTournament.matches.find((m) => m.round === numRounds - 1);
206:   if (finalMatch && finalMatch.isCompleted && finalMatch.winnerId) {
207:     updatedTournament.isCompleted = true;
208:     updatedTournament.championId = finalMatch.winnerId;
209:     const loserId = finalMatch.player1Id === finalMatch.winnerId ? finalMatch.player2Id : finalMatch.player1Id;
210:     if (loserId) updatedTournament.runnerUpId = loserId;
211:   }
212: 
213:   return updatedTournament;
214: }
