245: export function advanceTournamentMatch(
246:   tournament: Tournament,
247:   matchId: string,
248:   winnerId: string,
249:   players: Player[]
250: ): { updatedTournament: Tournament; updatedPlayers: Player[] } {
251:   const updatedTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
252:   const match = updatedTournament.matches.find((m) => m.id === matchId);
253:   if (!match) return { updatedTournament, updatedPlayers: players };
254: 
255:   match.isCompleted = true;
256:   match.winnerId = winnerId;
257: 
258:   // Propagate to next match
259:   if (match.nextMatchId) {
260:     const nextMatch = updatedTournament.matches.find((m) => m.id === match.nextMatchId);
261:     if (nextMatch) {
262:       if (match.nextMatchSlot === 1) {
263:         nextMatch.player1Id = winnerId;
264:         const winnerObj = players.find((p) => p.id === winnerId);
265:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed1 = winnerObj.rank;
266:       } else {
267:         nextMatch.player2Id = winnerId;
268:         const winnerObj = players.find((p) => p.id === winnerId);
269:         if (winnerObj && winnerObj.rank <= 32) nextMatch.seed2 = winnerObj.rank;
270:       }
271:     }
272:   }
273: 
274:   // Check if final match
275:   const maxRound = Math.log2(updatedTournament.drawSize) - 1;
276:   if (match.round === maxRound) {
277:     updatedTournament.isCompleted = true;
278:     updatedTournament.championId = winnerId;
279:     const loserId = match.player1Id === winnerId ? match.player2Id : match.player1Id;
280:     if (loserId) updatedTournament.runnerUpId = loserId;
281:   }
282: 
283:   // Update player form / match records
284:   const updatedPlayers = players.map((p) => {
285:     if (p.id === winnerId) {
286:       return {
287:         ...p,
288:         matchesWon: p.matchesWon + 1,
289:         form: Math.min(1.25, p.form + 0.01),
290:       };
291:     }
292:     const loserId = match.player1Id === winnerId ? match.player2Id : match.player1Id;
293:     if (p.id === loserId) {
294:       return {
295:         ...p,
296:         matchesLost: p.matchesLost + 1,
297:         form: Math.max(0.75, p.form - 0.015),
298:       };
299:     }
300:     return p;
301:   });
302: 
303:   return { updatedTournament, updatedPlayers };
304: }
