306: export function finalizeTournamentAndDistributePoints(
307:   tournament: Tournament,
308:   players: Player[]
309: ): Player[] {
310:   const pointsMap = new Map<string, { points: number; prize: number; wonTitle: boolean }>();
311: 
312:   tournament.matches.forEach((m) => {
313:     if (m.isCompleted && m.player1Id && m.player2Id) {
314:       const loserId = m.winnerId === m.player1Id ? m.player2Id : m.player1Id;
315:       const isWinner = m.winnerId;
316: 
317:       let roundPoints = 0;
318:       let roundPrize = 0;
319: 
320:       if (m.roundName === 'Финал') {
321:         if (isWinner) {
322:           pointsMap.set(isWinner, {
323:             points: tournament.pointsWinner,
324:             prize: Math.round(tournament.prizeMoneyPool * 0.22),
325:             wonTitle: true,
326:           });
327:         }
328:         if (loserId) {
329:           pointsMap.set(loserId, {
330:             points: tournament.pointsFinalist,
331:             prize: Math.round(tournament.prizeMoneyPool * 0.12),
332:             wonTitle: false,
333:           });
334:         }
335:       } else if (m.roundName === '1/2 финала' && loserId && !pointsMap.has(loserId)) {
336:         roundPoints = tournament.pointsSemi;
337:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.06);
338:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
339:       } else if (m.roundName === '1/4 финала' && loserId && !pointsMap.has(loserId)) {
340:         roundPoints = tournament.pointsQuarter;
341:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.035);
342:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
343:       } else if (m.roundName === '1/8 финала' && loserId && !pointsMap.has(loserId)) {
344:         roundPoints = tournament.pointsR16;
345:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.018);
346:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
347:       } else if (m.roundName === '1/16 финала' && loserId && !pointsMap.has(loserId)) {
348:         roundPoints = tournament.pointsR32;
349:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.009);
350:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
351:       } else if (m.roundName === '1/32 финала' && loserId && !pointsMap.has(loserId)) {
352:         roundPoints = tournament.pointsR64;
353:         roundPrize = Math.round(tournament.prizeMoneyPool * 0.004);
354:         pointsMap.set(loserId, { points: roundPoints, prize: roundPrize, wonTitle: false });
355:       }
356:     }
357:   });
358: 
359:   const updatedPlayers = players.map((p) => {
360:     if (p.tour !== tournament.tour) return p;
361: 
362:     const tourneyPointsHistory = p.tournamentPoints || {};
363:     // Defended points = points earned at this specific tournament in the previous season edition
364:     const defendedPoints = tourneyPointsHistory[tournament.id] || 0;
365: 
366:     let earnedPoints = 0;
367:     let prize = 0;
368:     let wonTitle = false;
369: 
370:     if (pointsMap.has(p.id)) {
371:       const award = pointsMap.get(p.id)!;
372:       earnedPoints = award.points;
373:       prize = award.prize;
374:       wonTitle = award.wonTitle;
375:     } else {
376:       const playedInTournament = tournament.matches.some(
377:         (m) => m.player1Id === p.id || m.player2Id === p.id
378:       );
379:       if (playedInTournament) {
380:         earnedPoints = tournament.pointsR128 || tournament.pointsR64 || 0;
381:       }
382:     }
383: 
384:     const updatedTourneyPoints = {
385:       ...tourneyPointsHistory,
386:       [tournament.id]: earnedPoints,
387:     };
388: 
389:     const netPointsChange = earnedPoints - defendedPoints;
390:     const newPoints = Math.max(0, p.points + netPointsChange);
391: 
392:     return {
393:       ...p,
394:       previousPoints: p.points,
395:       points: newPoints,
396:       tournamentPoints: updatedTourneyPoints,
397:       prizeMoney: p.prizeMoney + prize,
398:       titles: wonTitle ? p.titles + 1 : p.titles,
399:       careerTitles: wonTitle ? p.careerTitles + 1 : p.careerTitles,
400:       grandSlams: wonTitle && tournament.category === 'Grand Slam' ? p.grandSlams + 1 : p.grandSlams,
401:     };
402:   });
403: 
404:   return recalculateRankings(updatedPlayers);
405: }
