407: export function recalculateRankings(players: Player[]): Player[] {
408:   const atp = players.filter((p) => p.tour === 'ATP' && !p.retired);
409:   const wta = players.filter((p) => p.tour === 'WTA' && !p.retired);
410:   const retired = players.filter((p) => p.retired);
411: 
412:   const sortTour = (list: Player[]) => {
413:     list.sort((a, b) => b.points - a.points || a.rank - b.rank);
414:     return list.map((p, idx) => ({
415:       ...p,
416:       previousRank: p.rank,
417:       rank: idx + 1,
418:     }));
419:   };
420: 
421:   const rankedAtp = sortTour(atp);
422:   const rankedWta = sortTour(wta);
423: 
424:   return [...rankedAtp, ...rankedWta, ...retired];
425: }
