427: export function simulateEntireTournament(
428:   tournament: Tournament,
429:   players: Player[]
430: ): { completedTournament: Tournament; updatedPlayers: Player[] } {
431:   let currTournament = JSON.parse(JSON.stringify(tournament)) as Tournament;
432:   let currPlayers = [...players];
433: 
434:   const totalRounds = Math.log2(currTournament.drawSize);
435: 
436:   for (let r = 0; r < totalRounds; r++) {
437:     const roundMatches = currTournament.matches.filter((m) => m.round === r && !m.isCompleted);
438:     for (const match of roundMatches) {
439:       if (match.player1Id && match.player2Id) {
440:         const p1 = currPlayers.find((p) => p.id === match.player1Id);
441:         const p2 = currPlayers.find((p) => p.id === match.player2Id);
442: 
443:         if (p1 && p2) {
444:           const sim = simulateFullMatch(p1, p2, currTournament.surface, currTournament.setsToWin);
445:           match.score = sim.score;
446:           const adv = advanceTournamentMatch(currTournament, match.id, sim.winnerId, currPlayers);
447:           currTournament = adv.updatedTournament;
448:           currPlayers = adv.updatedPlayers;
449:         }
450:       }
451:     }
452:   }
453: 
454:   currPlayers = finalizeTournamentAndDistributePoints(currTournament, currPlayers);
455:   return { completedTournament: currTournament, updatedPlayers: currPlayers };
456: }

